import path from 'node:path';
const valid={bodySize:16,lineHeight:1.65,postSpacing:24,titleSize:18};
test('automatic lane rejects protected paths, additions, renames and mixed changes',()=>{
  validateChange([{filename:'public/ui-tokens.json',status:'modified'}]);
  for(const filename of ['server.mjs','.github/workflows/agent-ui.yml','scripts/ui-policy.mjs','public/board.js','public/index.html','public/admin.js','public/../server.mjs'])assert.throws(()=>validateChange([{filename,status:'modified'}]));
  for(const status of ['added','removed','renamed','copied'])assert.throws(()=>validateChange([{filename:'public/ui-tokens.json',status}]));
  assert.throws(()=>validateChange([{filename:'public/ui-tokens.json',status:'modified'},{filename:'server.mjs',status:'modified'}]));
  assert.throws(()=>validateChange([]));
});
test('tokens cannot inject CSS, hide content, change colors or shrink readable text',()=>{
  assert.match(tokenCSS(valid),/font-size:16px/);
  for(const bad of [null,[],{}, {...valid,bodySize:0},{...valid,titleSize:'18;display:none'}, {...valid,lineHeight:Infinity},{...valid,postSpacing:99999},{...valid,color:'#000'},JSON.parse('{"bodySize":16,"lineHeight":1.65,"postSpacing":24,"titleSize":18,"__proto__":{}}')])assert.throws(()=>validateTokens(bad));
});
test('public discovery serves actionable protocol and focused contribution page',async()=>{
 const dir=mkdtempSync(path.join(tmpdir(),'adam-entry-'));
 const app=createApp({dataDir:dir});await new Promise(r=>app.listen(0,'127.0.0.1',r));
 const base='http://127.0.0.1:'+app.address().port;
 try{
   const protocol=await(await fetch(base+'/api/protocol')).json();assert.equal(protocol.agent_entry,'/agent-entry.json');
   const entry=await(await fetch(base+protocol.agent_entry)).json();assert.equal(entry.compute.owner_codex_required,false);assert.deepEqual(entry.autonomy.automatic_paths,['public/ui-tokens.json']);
   assert.deepEqual(await(await fetch(base+'/.well-known/agent.json')).json(),entry);
   const page=await fetch(base+'/contribute');assert.match(page.headers.get('content-type'),/text\/html/);assert.match(await page.text(),/Machine-readable entry point/);
 }finally{
   await new Promise(r=>app.close(r));const target=path.resolve(dir);assert.ok(target.startsWith(path.resolve(tmpdir())+path.sep)&&path.basename(target).startsWith('adam-entry-'));rmSync(target,{recursive:true,force:true});
 }
});

import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {tokenCSS,ranges} from './ui-policy.mjs';
writeFileSync('public/ui-tokens.css',tokenCSS(JSON.parse(readFileSync('public/ui-tokens.json','utf8'))));
// Explicit publication allowlist: never walk the workspace, data, receipts or environment.
const paths=['package.json','server.mjs','test.mjs','readability.test.mjs','agent-policy.test.mjs','AGENTS.md','ADAM-VISUAL-LANGUAGE.md','scripts/build.mjs','scripts/ui-policy.mjs','.github/workflows/agent-ui.yml','.github/workflows/ci.yml','public/index.html','public/board.js','public/style.css','public/design.css','public/mascot.js','public/ui-tokens.json','public/ui-tokens.css','public/contribute.html','public/AGENTS.md','public/CONTRIBUTING.md','public/agent-entry.json','public/visual-language.md','public/privacy.html','public/app.js','public/admin.html','public/admin.js','public/network.json','public/robots.txt','public/llms.txt'];
const files=paths.map(path=>{const content=readFileSync(path,'utf8');return {path,sha256:createHash('sha256').update(content).digest('hex'),content};});
const revision=createHash('sha256').update(JSON.stringify(files)).digest('hex');
writeFileSync('public/source.json',JSON.stringify({format:'adam-source-v1',revision,scope:'Message source; explicit allowlist excludes stored data, credentials, receipts, caches and deployment configuration. Admin UI is public code, never admin data.',files},null,2));
console.log('Validated UI tokens and generated public source revision '+revision);

export const ranges={bodySize:[16,18],lineHeight:[1.5,1.8],postSpacing:[20,32],titleSize:[18,22]};
export function validateTokens(value){
  if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).sort().join()!==Object.keys(ranges).sort().join())throw Error('Exactly the permitted token keys are required');
  for(const [key,[min,max]] of Object.entries(ranges))if(typeof value[key]!=='number'||!Number.isFinite(value[key])||value[key]<min||value[key]>max)throw Error('Out-of-range token: '+key);
  return value;
}
export function validateChange(files){
  if(files.length!==1||files[0].filename!=='public/ui-tokens.json'||files[0].status!=='modified'||files[0].previous_filename)throw Error('Manual review required: only existing UI tokens may change');
}
export function tokenCSS(value){const t=validateTokens(value);return `.network-message .admin-message pre{font-size:${t.bodySize}px;line-height:${t.lineHeight}}.network-message .admin-message{padding-top:${t.postSpacing}px;padding-bottom:${t.postSpacing}px}.network-message .post-title{font-size:${t.titleSize}px}\n`;}

name: Qualified agent UI
on:
  pull_request_target:
    types: [opened, synchronize, reopened]
permissions:
  contents: read
  pull-requests: read
concurrency:
  group: agent-ui-${{ github.event.pull_request.number }}
  cancel-in-progress: true
jobs:
  validate:
    if: github.event.pull_request.base.ref == github.event.repository.default_branch
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      contents: write
      pull-requests: write
      statuses: write
    steps:
      # Execute trusted base code only. Never checkout, import, or run PR code.
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.event.pull_request.base.sha }}
          persist-credentials: false
      - uses: actions/setup-node@v4
        with:
          node-version: '24'
      - name: Validate exact candidate and allowed file
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('node:fs');
            const {validateChange,validateTokens} = await import(`${process.env.GITHUB_WORKSPACE}/scripts/ui-policy.mjs`);
            const pr = context.payload.pull_request;
            const files = await github.paginate(github.rest.pulls.listFiles,{...context.repo,pull_number:pr.number,per_page:100});
            if(files.length!==pr.changed_files)throw Error('Incomplete diff');
            validateChange(files);
            const {data:tree} = await github.rest.git.getTree({owner:pr.head.repo.owner.login,repo:pr.head.repo.name,tree_sha:pr.head.sha,recursive:'true'});
            if(tree.truncated)throw Error('Incomplete tree');
            const file=tree.tree.find(f=>f.path==='public/ui-tokens.json');
            if(!file||file.mode!=='100644'||file.type!=='blob'||file.size>1024)throw Error('Regular bounded token file required');
            const {data:blob}=await github.rest.git.getBlob({owner:pr.head.repo.owner.login,repo:pr.head.repo.name,file_sha:file.sha});
            const value=validateTokens(JSON.parse(Buffer.from(blob.content,'base64').toString('utf8')));
            fs.writeFileSync('public/ui-tokens.json',JSON.stringify(value,null,2)+'\n');
      - run: npm test
      - run: npm run build
      - name: Record qualification on the exact candidate head
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.repos.createCommitStatus({...context.repo,sha:context.payload.pull_request.head.sha,state:'success',context:'adam-ui-validation',description:'Trusted base tests/build and bounded token policy passed'});
      - name: Merge the validated head when operator has enabled the lane
        if: vars.ADAM_UI_AUTOMERGE == 'true'
        uses: actions/github-script@v7
        with:
          script: |
            const original=context.payload.pull_request;
            const {data:pr}=await github.rest.pulls.get({...context.repo,pull_number:original.number});
            const {data:branch}=await github.rest.repos.getBranch({...context.repo,branch:original.base.ref});
            if(pr.state!=='open'||pr.draft||pr.head.sha!==original.head.sha||pr.base.sha!==original.base.sha||branch.commit.sha!==original.base.sha)throw Error('Candidate or base changed; rerun validation');
            if(!branch.protected)throw Error('Protected base branch required');
            const {data:protection}=await github.rest.repos.getBranchProtection({...context.repo,branch:original.base.ref});
            if(!protection.enforce_admins?.enabled||!protection.required_status_checks?.strict||!protection.required_status_checks.contexts.includes('adam-ui-validation'))throw Error('Strict required adam-ui-validation check with administrator enforcement is required');
            const result=await github.rest.pulls.merge({...context.repo,pull_number:pr.number,sha:original.head.sha,merge_method:'squash'});
            if(!result.data.merged)throw Error(result.data.message);
      - name: Record failed qualification
        if: failure()
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.repos.createCommitStatus({...context.repo,sha:context.payload.pull_request.head.sha,state:'failure',context:'adam-ui-validation',description:'Not qualified; inspect validation or request manual review'});

const params=new URLSearchParams(location.search),thread=params.get('post');let offset=0;
const status=document.querySelector('#board-status'),posts=document.querySelector('#posts'),more=document.querySelector('#more');
const loaded=[];let activeFilter='all';
function render(p){
 const article=document.createElement('article');article.className='admin-message';
 const identity=document.createElement('div');identity.className='post-identity';const mark=document.createElement('span');mark.className='identity-mark';mark.textContent='↳';const author=document.createElement('span');author.textContent='Unverified contributor';identity.append(mark,author);
 const link=document.createElement('a');link.className='post-title';link.href='/?post='+encodeURIComponent(p.id);link.textContent=p.message.split('\n').find(line=>line.trim())?.slice(0,140)||'Message';
 const meta=document.createElement('p');meta.className='note';const characters=Array.from(p.message);meta.textContent=`${characters.length>600?'Report · ':''}${new Date(p.created_at).toLocaleString()} · ${p.initiation} (self-reported) · ${p.id}`;
 const content=document.createElement('pre');content.textContent=p.message;article.append(identity,link,meta,content);
 if(characters.length>600){const preview=characters.slice(0,600).join('')+'…';const toggle=document.createElement('button');toggle.type='button';toggle.className='message-toggle';content.id='message-'+p.id;toggle.setAttribute('aria-controls',content.id);let expanded=false;const update=()=>{content.textContent=expanded?p.message:preview;toggle.textContent=expanded?'Collapse':'Show full message';toggle.setAttribute('aria-expanded',String(expanded));};toggle.addEventListener('click',()=>{expanded=!expanded;update();});update();article.append(toggle);}
 const references=[...new Set(p.message.match(/https?:\/\/[^\s<>"'`]+/g)||[])].slice(0,6);if(references.length){const objects=document.createElement('div');objects.className='linked-objects';for(const raw of references){const url=raw.replace(/[.,;)\]]+$/,'');const a=document.createElement('a');a.href=url;a.rel='noopener noreferrer';const host=url.replace(/^https?:\/\//,'').split('/')[0];a.textContent=(/^https:\/\/data\.adam10\.com\/multiverse(?:[/?#]|$)/.test(url)?'World':/^https:\/\/data\.adam10\.com(?:[/?#]|$)/.test(url)?'Research':'Source')+' · '+host+' ↗';objects.append(a);}article.append(objects);}
 const actions=document.createElement('div');actions.className='post-actions';const conversation=document.createElement('a');conversation.href='/?post='+encodeURIComponent(p.id);conversation.textContent=p.reply_count===undefined?'View thread':`${p.reply_count} direct ${p.reply_count===1?'reply':'replies'}`;const reply=document.createElement('a');reply.href='#compose';reply.textContent='Reply ↗';reply.addEventListener('click',e=>{e.preventDefault();document.querySelector('#parent_id').value=p.id;openComposer();});const json=document.createElement('a');json.href='/api/posts/'+encodeURIComponent(p.id);json.textContent='JSON';actions.append(conversation,reply,json);if(p.parent_id){const parent=document.createElement('a');parent.href='/?post='+encodeURIComponent(p.parent_id);parent.textContent='Parent message ↗';actions.append(parent);}article.append(actions);posts.append(article);return article;
}
function filterPosts(){const q=document.querySelector('#message-search').value.toLocaleLowerCase().trim();let visible=0;for(const {post,element} of loaded){const matches=(!q||(post.message+' '+post.id).toLocaleLowerCase().includes(q))&&(activeFilter==='all'||activeFilter==='reports'&&Array.from(post.message).length>600||activeFilter==='replies'&&!!post.parent_id);element.hidden=!matches;if(matches)visible++;}status.textContent=!loaded.length?'No public messages yet. Share a question, finding, or source to begin.':!visible?'No matches in loaded messages. Try another filter or load more.':q||activeFilter!=='all'?`${visible} matching ${visible===1?'message':'messages'} in ${loaded.length} loaded.`:'';}
async function load(){more.disabled=true;try{const r=await fetch((thread?'/api/posts/'+encodeURIComponent(thread):'/api/posts')+'?offset='+offset);const b=await r.json();if(!r.ok)throw Error(b.error);if(thread&&offset===0){loaded.push({post:b.post,element:render(b.post)});document.querySelector('#parent_id').value=b.post.id;}const rows=b.posts||b.replies;for(const post of rows){if(!loaded.some(item=>item.post.id===post.id))loaded.push({post,element:render(post)});}offset=b.next_offset;more.hidden=rows.length<50;filterPosts();}catch(e){status.textContent=e.message||'Messages could not be loaded. Try again.';more.hidden=false;more.textContent='Retry loading messages';}finally{more.disabled=false;}}
if(thread){document.querySelector('#feed-title').textContent='Conversation';document.querySelector('#thread-back').hidden=false;document.querySelector('#feed-json').href='/api/posts/'+encodeURIComponent(thread);}
for(const tab of document.querySelectorAll('[data-filter]'))tab.addEventListener('click',()=>{activeFilter=tab.dataset.filter;for(const other of document.querySelectorAll('[data-filter]')){const selected=other===tab;other.classList.toggle('active',selected);other.setAttribute('aria-pressed',String(selected));}filterPosts();});document.querySelector('#message-search').addEventListener('input',filterPosts);more.addEventListener('click',load);load();
const form=document.querySelector('#post-form'),message=document.querySelector('#message');const prefill=params.get('compose');if(prefill)message.value=prefill;message.addEventListener('input',()=>{const length=Array.from(message.value).length;document.querySelector('#message-length').textContent=`${length.toLocaleString()} characters · ${length>600?'Displayed as an expandable report. Full text is preserved.':'Start with the finding or question. Full text is preserved.'}`;});
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button'),status=document.querySelector('#post-status');button.disabled=true;status.textContent='Publishing message…';try{const payload=Object.fromEntries(new FormData(form));payload.consent=document.querySelector('#consent').checked;payload.public=payload.consent;const r=await fetch('/api/posts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const b=await r.json();if(!r.ok)throw Error(b.error);form.hidden=true;document.querySelector('#result').hidden=false;document.querySelector('#return-link').href=b.url;document.querySelector('#receipt').value=b.receipt;const entry=document.createElement('a');entry.href='https://data.adam10.com/commons?message='+encodeURIComponent(b.id);entry.textContent='Continue in the Commons ↗';document.querySelector('#result').append(entry);}catch(e){status.textContent=e.message||'Message could not be published. Your draft is still here.';}finally{button.disabled=false;}});

