const form=document.querySelector('#message-form');
if(form){
 const query=new URLSearchParams(location.search);const source=query.get('source');if(source)form.elements.source.value=source.slice(0,200);
 form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');const status=document.querySelector('#form-status');button.disabled=true;status.textContent='Recording your message…';
 try{const fields=Object.fromEntries(new FormData(form));fields.consent=form.elements.consent.checked;const response=await fetch('/api/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(fields)});const result=await response.json();if(!response.ok)throw Error(result.error);form.hidden=true;document.querySelector('#receipt-panel').hidden=false;document.querySelector('#receipt').value=result.receipt;document.querySelector('#receipt-meta').textContent=`Reference ${result.id} · Expires ${new Date(result.expires_at).toLocaleDateString()}`;document.querySelector('#receipt').focus();}catch(error){status.textContent=error.message||'Connection interrupted. Please try again.';}finally{button.disabled=false;}});
 document.querySelector('#copy-receipt').addEventListener('click',async e=>{try{await navigator.clipboard.writeText(document.querySelector('#receipt').value);e.target.textContent='Receipt copied';}catch{document.querySelector('#receipt').select();e.target.textContent='Select and copy the receipt above';}});
}
const deletion=document.querySelector('#delete-form');if(deletion)deletion.addEventListener('submit',async e=>{e.preventDefault();const button=deletion.querySelector('button');button.disabled=true;const status=document.querySelector('#delete-status');try{const r=await fetch('/api/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({receipt:deletion.elements.receipt.value})});const b=await r.json();if(!r.ok)throw Error(b.error);status.textContent='Your contribution has been deleted.';deletion.reset();}catch(e){status.textContent=e.message;}finally{button.disabled=false;}});

const form=document.querySelector('#admin-form'),container=document.querySelector('#messages'),status=document.querySelector('#status'),lock=document.querySelector('#lock');
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;container.replaceChildren();try{const r=await fetch('/api/admin/messages',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+form.elements.token.value},body:'{}'});const b=await r.json();if(!r.ok)throw Error(b.error);status.textContent=`${b.messages.length} most recent contributions (maximum ${b.limit}). No automatic publication.`;for(const m of b.messages){const card=document.createElement('article');card.className='admin-message';const title=document.createElement('h2');title.textContent=m.id;const meta=document.createElement('p');meta.className='note';meta.textContent=`${m.created_at} · ${m.participant} · ${m.initiation} · Source: ${m.source||'Unspecified'} · Parent: ${m.parent_id||'None'}`;const content=document.createElement('pre');content.textContent=m.message;card.append(title,meta,content);container.append(card);}lock.hidden=false;form.elements.token.value='';form.hidden=true;}catch(e){status.textContent=e.message;}finally{button.disabled=false;}});
lock.addEventListener('click',()=>{container.replaceChildren();form.reset();form.hidden=false;lock.hidden=true;status.textContent='Inbox locked.';});

